/**
 * FILE: concept_3_compounding_dividend_tree.js
 * THEME: Finance & Investment — Nurturing Wealth & Compounding Dividend Tree
 * STYLE: Modern Flat Vector with Solid Chroma Green Screen (#00FF00)
 * ASPECT RATIO: 16:9 | RESOLUTION READY: FHD / 2K / 4K (Ultra HD)
 * DURATION: 20 Seconds Seamless Loop | SCENES: 1
 * TARGET EXPORT BITRATE: 100 Mbps (Uncompressed Crisp Vector Edges, Zero Glow/Bloom)
 */

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const s = minSide / 1080;
  const cx = width * 0.5;
  const cy = height * 0.5;

  // Fundamental harmonic phases for 100% seamless 20-second loop
  const tau = Math.PI * 2;
  const p1 = sceneProgress * tau + currentScene * 0;
  const p2 = sceneProgress * tau * 2;
  const p3 = sceneProgress * tau * 3;
  const p4 = sceneProgress * tau * 4;

  // Color Palette (Crisp Commercial Flat Vector, Zero Glow)
  const COL = {
    greenScreen: '#00FF00',
    outline: '#162035',
    surfaceWhite: '#FFFFFF',
    surfaceLight: '#F1F5F9',
    surfaceMuted: '#CBD5E1',
    slateDark: '#334155',
    slateMid: '#64748B',
    potTerracotta: '#F97316',
    potTerracottaDark: '#EA580C',
    potCream: '#FFFBEB',
    stemGreen: '#15803D',
    leafLight: '#86EFAC',
    leafMid: '#22C55E',
    leafDark: '#16A34A',
    canTealLight: '#67E8F9',
    canTealMid: '#06B6D4',
    canTealDark: '#0891B2',
    waterBlueLight: '#BAE6FD',
    waterBlueMid: '#38BDF8',
    waterBlueDark: '#0284C7',
    goldLight: '#FEF08A',
    goldMid: '#FACC15',
    goldDark: '#EAB308',
    goldDeep: '#CA8A04',
    bookBlue: '#2563EB',
    bookBlueDark: '#1D4ED8',
    bookPurple: '#7C3AED',
    bookPurpleDark: '#6D28D9',
    coralAccent: '#FB7185'
  };

  const strokeW = 5.5 * s;
  const thinStrokeW = 3.5 * s;

  ctx.save();
  ctx.shadowBlur = 0;
  ctx.shadowColor = 'transparent';
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';

  // 1. SOLID GREEN SCREEN BACKGROUND
  ctx.fillStyle = COL.greenScreen;
  ctx.fillRect(0, 0, width, height);

  // Helper: Rounded Rectangle Path
  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function fillAndStroke(fillColor, outlineColor, lineWidth) {
    if (fillColor) {
      ctx.fillStyle = fillColor;
      ctx.fill();
    }
    if (outlineColor && lineWidth > 0) {
      ctx.strokeStyle = outlineColor;
      ctx.lineWidth = lineWidth;
      ctx.stroke();
    }
  }

  // Helper: Crisp Vector Dollar Sign
  function drawVectorDollar(centerX, centerY, scaleSize, color, lineW) {
    const w = 13 * scaleSize;
    const h = 20 * scaleSize;
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineW;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    ctx.beginPath();
    ctx.moveTo(centerX + w * 0.75, centerY - h * 0.45);
    ctx.bezierCurveTo(
      centerX + w * 0.75, centerY - h * 0.85,
      centerX - w * 0.85, centerY - h * 0.85,
      centerX - w * 0.85, centerY - h * 0.35
    );
    ctx.bezierCurveTo(
      centerX - w * 0.85, centerY + h * 0.02,
      centerX + w * 0.85, centerY - h * 0.02,
      centerX + w * 0.85, centerY + h * 0.40
    );
    ctx.bezierCurveTo(
      centerX + w * 0.85, centerY + h * 0.85,
      centerX - w * 0.75, centerY + h * 0.85,
      centerX - w * 0.75, centerY + h * 0.45
    );
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(centerX, centerY - h * 0.98);
    ctx.lineTo(centerX, centerY + h * 0.98);
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Crisp Vector Upward Arrow
  function drawUpArrow(centerX, centerY, size, color, lineW) {
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineW;
    ctx.beginPath();
    ctx.moveTo(centerX, centerY + size * 0.7);
    ctx.lineTo(centerX, centerY - size * 0.65);
    ctx.moveTo(centerX - size * 0.55, centerY - size * 0.1);
    ctx.lineTo(centerX, centerY - size * 0.7);
    ctx.lineTo(centerX + size * 0.55, centerY - size * 0.1);
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Crisp Pointed Botanical Vector Leaf with Center Vein
  function drawVectorLeaf(x, y, length, widthLeaf, angleRad) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angleRad);

    // Leaf blade from (0,0) base to (length, 0) tip
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.quadraticCurveTo(length * 0.45, -widthLeaf * 0.65, length, 0);
    ctx.quadraticCurveTo(length * 0.45, widthLeaf * 0.65, 0, 0);
    ctx.closePath();
    fillAndStroke(COL.leafMid, COL.outline, thinStrokeW);

    // Upper half highlight fill (clipped cleanly)
    ctx.save();
    ctx.clip();
    ctx.fillStyle = COL.leafLight;
    ctx.fillRect(0, -widthLeaf, length, widthLeaf);
    ctx.restore();

    // Re-stroke outer leaf edge and central vein
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.quadraticCurveTo(length * 0.45, -widthLeaf * 0.65, length, 0);
    ctx.quadraticCurveTo(length * 0.45, widthLeaf * 0.65, 0, 0);
    ctx.closePath();
    fillAndStroke(null, COL.outline, thinStrokeW);

    ctx.strokeStyle = COL.outline;
    ctx.lineWidth = 2.8 * s;
    ctx.beginPath();
    ctx.moveTo(4 * s, 0);
    ctx.lineTo(length * 0.82, 0);
    ctx.stroke();

    ctx.restore();
  }

  // Helper: Crisp Gold Coin Medallion
  function drawGoldMedallion(centerX, centerY, radius, dollarScale) {
    ctx.beginPath();
    ctx.arc(centerX, centerY, radius, 0, tau);
    fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

    ctx.beginPath();
    ctx.arc(centerX, centerY, radius * 0.74, 0, tau);
    fillAndStroke(COL.goldLight, COL.outline, 2.5 * s);

    drawVectorDollar(centerX, centerY, dollarScale, COL.outline, 3.2 * s);
  }

  // Helper: Side-View Stacked Coin Cylinder
  function drawCoinCylinder(centerX, topY, coinW, coinH) {
    roundedRectPath(centerX - coinW * 0.5, topY, coinW, coinH, 7 * s);
    fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

    roundedRectPath(centerX - coinW * 0.40, topY + 4 * s, coinW * 0.20, coinH - 8 * s, 3.5 * s);
    fillAndStroke(COL.goldLight, null, 0);

    roundedRectPath(centerX + coinW * 0.20, topY + 4 * s, coinW * 0.20, coinH - 8 * s, 3.5 * s);
    fillAndStroke(COL.goldDeep, null, 0);

    roundedRectPath(centerX - coinW * 0.5, topY, coinW, coinH, 7 * s);
    fillAndStroke(null, COL.outline, thinStrokeW);
  }

  // =========================================================================
  // 2. STRUCTURAL BASELINE PLATFORM & NON-INTERSECTING DATA BRIDGES
  // =========================================================================
  const baseLineY = cy + 395 * s;

  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = strokeW;
  ctx.beginPath();
  ctx.moveTo(cx - 735 * s, baseLineY);
  ctx.lineTo(cx + 735 * s, baseLineY);
  ctx.stroke();

  // Outer baseline accent ticks
  const tickShift = Math.sin(p2) * 6 * s;
  ctx.beginPath();
  ctx.moveTo(cx - 810 * s - tickShift, baseLineY);
  ctx.lineTo(cx - 760 * s - tickShift, baseLineY);
  ctx.moveTo(cx + 760 * s + tickShift, baseLineY);
  ctx.lineTo(cx + 810 * s + tickShift, baseLineY);
  ctx.stroke();

  // Sub-platform line
  ctx.beginPath();
  ctx.moveTo(cx - 360 * s, baseLineY + 18 * s);
  ctx.lineTo(cx + 360 * s, baseLineY + 18 * s);
  ctx.stroke();

  // Dedicated Horizontal Data Bridges in Lower Corridor (y = cy + 190 * s)
  // Left gap: [cx - 285*s, cx - 195*s] | Right gap: [cx + 195*s, cx + 295*s]
  const bridgeY = cy + 190 * s;
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = thinStrokeW;
  ctx.beginPath();
  ctx.moveTo(cx - 275 * s, bridgeY);
  ctx.lineTo(cx - 205 * s, bridgeY);
  ctx.moveTo(cx + 205 * s, bridgeY);
  ctx.lineTo(cx + 285 * s, bridgeY);
  ctx.stroke();

  const bProgL = (sceneProgress * 4) % 1;
  ctx.beginPath();
  ctx.arc(cx - 268 * s + bProgL * 56 * s, bridgeY, 6 * s, 0, tau);
  fillAndStroke(COL.leafMid, COL.outline, 2.5 * s);

  const bProgR = (sceneProgress * 4 + 0.5) % 1;
  ctx.beginPath();
  ctx.arc(cx + 212 * s + bProgR * 66 * s, bridgeY, 6 * s, 0, tau);
  fillAndStroke(COL.goldMid, COL.outline, 2.5 * s);

  // =========================================================================
  // 3. LEFT-TOP ZONE: COMPOUNDING GROWTH BAR & TREND ANALYTICS CARD
  // Bounding Box: x in [cx - 685*s, cx - 285*s], y in [cy - 360*s, cy - 35*s]
  // =========================================================================
  const ltFloatY = Math.sin(p2) * 4.5 * s;
  const ltX = cx - 685 * s;
  const ltY = cy - 360 * s + ltFloatY;
  const ltW = 400 * s;
  const ltH = 315 * s;

  roundedRectPath(ltX, ltY, ltW, ltH, 20 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);

  // Header Bar inside Left-Top Card
  roundedRectPath(ltX + 18 * s, ltY + 18 * s, ltW - 36 * s, 46 * s, 12 * s);
  fillAndStroke(COL.surfaceLight, COL.outline, thinStrokeW);

  // Green Yield Badge on Left of Header
  roundedRectPath(ltX + 26 * s, ltY + 25 * s, 96 * s, 32 * s, 8 * s);
  fillAndStroke(COL.leafMid, COL.outline, 2.8 * s);
  drawUpArrow(ltX + 48 * s, ltY + 41 * s, 16 * s, COL.outline, 3.5 * s);
  roundedRectPath(ltX + 68 * s, ltY + 36 * s, 42 * s, 10 * s, 5 * s);
  fillAndStroke(COL.surfaceWhite, null, 0);

  // Header Title Bar & Status Dot
  roundedRectPath(ltX + 140 * s, ltY + 35 * s, 175 * s, 12 * s, 6 * s);
  fillAndStroke(COL.slateDark, null, 0);
  ctx.beginPath();
  ctx.arc(ltX + ltW - 42 * s, ltY + 41 * s, 9 * s, 0, tau);
  fillAndStroke(COL.goldMid, COL.outline, 2.5 * s);

  // Inner Chart Frame (y: ltY + 80*s, height: 215*s)
  const cFrameX = ltX + 18 * s;
  const cFrameY = ltY + 80 * s;
  const cFrameW = ltW - 36 * s;
  const cFrameH = 215 * s;

  roundedRectPath(cFrameX, cFrameY, cFrameW, cFrameH, 14 * s);
  fillAndStroke(COL.surfaceLight, COL.outline, thinStrokeW);

  // Horizontal Grid Lines
  ctx.strokeStyle = COL.surfaceMuted;
  ctx.lineWidth = 2 * s;
  for (let g = 1; g <= 3; g++) {
    const gy = cFrameY + (cFrameH / 4) * g;
    ctx.beginPath();
    ctx.moveTo(cFrameX + 16 * s, gy);
    ctx.lineTo(cFrameX + cFrameW - 16 * s, gy);
    ctx.stroke();
  }

  // 5 Ascending Compounding Bars (occupying lower 60% of chart frame)
  // Plus a strictly separated Trend Line & Nodes in upper 30% of chart frame
  const barCount = 5;
  const barW = 34 * s;
  const barSpacing = (cFrameW - 76 * s) / (barCount - 1);
  const barBottomY = cFrameY + cFrameH - 14 * s;
  const baseRatios = [0.22, 0.31, 0.42, 0.54, 0.68];
  const nodePts = [];

  for (let i = 0; i < barCount; i++) {
    const bCenterX = cFrameX + 38 * s + i * barSpacing;
    const mod = 0.05 * Math.sin(p2 - i * 0.7);
    const bh = (baseRatios[i] + mod) * (cFrameH - 42 * s);
    const by = barBottomY - bh;

    const barCol = i === 4 ? COL.goldMid : (i >= 2 ? COL.leafMid : COL.waterBlueMid);
    roundedRectPath(bCenterX - barW * 0.5, by, barW, bh, 7 * s);
    fillAndStroke(barCol, COL.outline, thinStrokeW);

    // Node sits strictly 24*s above the top of its bar (zero overlap!)
    nodePts.push({ x: bCenterX, y: by - 24 * s });
  }

  // Draw Trend Line connecting nodePts
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = 4 * s;
  ctx.beginPath();
  for (let i = 0; i < nodePts.length; i++) {
    if (i === 0) ctx.moveTo(nodePts[i].x, nodePts[i].y);
    else ctx.lineTo(nodePts[i].x, nodePts[i].y);
  }
  ctx.stroke();

  for (let i = 0; i < nodePts.length; i++) {
    ctx.beginPath();
    ctx.arc(nodePts[i].x, nodePts[i].y, 7 * s, 0, tau);
    fillAndStroke(i === 4 ? COL.goldMid : COL.surfaceWhite, COL.outline, 2.8 * s);
  }

  // =========================================================================
  // 4. LEFT-BOTTOM ZONE: SEED CAPITAL PANEL & GOLD RESERVES PEDESTAL
  // Bounding Box: x in [cx - 685*s, cx - 285*s], y in [cy + 25*s, cy + 395*s]
  // =========================================================================
  const lbFloatY = Math.cos(p2) * 4 * s;
  const lbX = cx - 685 * s;
  const lbY = cy + 25 * s + lbFloatY;
  const lbW = 400 * s;
  const lbCardH = 185 * s;

  // 4A. Upper Portfolio Seed Allocation Panel
  roundedRectPath(lbX, lbY, lbW, lbCardH, 20 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);

  // Left Segmented Donut Ring inside Seed Panel
  const dCX = lbX + 82 * s;
  const dCY = lbY + lbCardH * 0.5;
  const dR = 54 * s;
  const dAngles = [0, tau * 0.45, tau * 0.78, tau];
  const dCols = [COL.leafMid, COL.waterBlueMid, COL.goldMid];

  for (let k = 0; k < 3; k++) {
    ctx.beginPath();
    ctx.moveTo(dCX, dCY);
    ctx.arc(dCX, dCY, dR, p1 + dAngles[k], p1 + dAngles[k + 1]);
    ctx.closePath();
    fillAndStroke(dCols[k], COL.outline, thinStrokeW);
  }
  ctx.beginPath();
  ctx.arc(dCX, dCY, 25 * s, 0, tau);
  fillAndStroke(COL.surfaceWhite, COL.outline, thinStrokeW);

  // Right 3 Progress Meters inside Seed Panel
  const mStartX = lbX + 162 * s;
  const mWidth = 212 * s;
  for (let m = 0; m < 3; m++) {
    const my = lbY + 34 * s + m * 48 * s;
    roundedRectPath(mStartX, my, 85 * s, 9 * s, 4.5 * s);
    fillAndStroke(COL.slateMid, null, 0);

    roundedRectPath(mStartX, my + 15 * s, mWidth, 18 * s, 9 * s);
    fillAndStroke(COL.surfaceLight, COL.outline, 2.5 * s);

    const mFill = (0.58 + 0.25 * Math.sin(p2 + m * 1.2)) * (mWidth - 6 * s);
    roundedRectPath(mStartX + 3 * s, my + 18 * s, mFill, 12 * s, 6 * s);
    fillAndStroke(dCols[m], null, 0);
  }

  // 4B. Lower Gold Bullion & Coin Reserves on Pedestal (Sitting on baseLineY)
  const pedLX = lbX;
  const pedLW = lbW;
  const pedLH = 24 * s;
  const pedLY = baseLineY - pedLH;

  roundedRectPath(pedLX, pedLY, pedLW, pedLH, 8 * s);
  fillAndStroke(COL.slateDark, COL.outline, strokeW);

  // Column 1 (Left): 2 Stacked Gold Bullion Bars (x center = lbX + 88*s, width = 128*s -> spans [24, 152])
  function drawBullionBar(centerX, bottomY, barW, barH) {
    const topW = barW * 0.78;
    ctx.beginPath();
    ctx.moveTo(centerX - bottomWHalf(barW), bottomY);
    ctx.lineTo(centerX - topW * 0.5, bottomY - barH);
    ctx.lineTo(centerX + topW * 0.5, bottomY - barH);
    ctx.lineTo(centerX + bottomWHalf(barW), bottomY);
    ctx.closePath();
    fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

    // Inner highlight trapezoid
    ctx.beginPath();
    ctx.moveTo(centerX - topW * 0.38, bottomY - barH + 7 * s);
    ctx.lineTo(centerX + topW * 0.38, bottomY - barH + 7 * s);
    ctx.lineTo(centerX + topW * 0.42, bottomY - 7 * s);
    ctx.lineTo(centerX - topW * 0.42, bottomY - 7 * s);
    ctx.closePath();
    fillAndStroke(COL.goldLight, null, 0);
  }
  function bottomWHalf(w) { return w * 0.5; }

  const bulCX = lbX + 88 * s;
  drawBullionBar(bulCX, pedLY, 126 * s, 38 * s);
  drawBullionBar(bulCX, pedLY - 38 * s, 110 * s, 36 * s);

  // Column 2 (Middle): 4 Stacked Gold Coins (x center = lbX + 222*s, width = 86*s -> spans [179, 265], 27*s clear gap!)
  const stackLCX = lbX + 222 * s;
  const cH = 24 * s;
  for (let c = 0; c < 4; c++) {
    drawCoinCylinder(stackLCX, pedLY - (c + 1) * cH, 86 * s, cH);
  }

  // Column 3 (Right): Front Gold Dollar Medallion on Stand (x center = lbX + 336*s, radius = 44*s -> spans [292, 380], 27*s clear gap!)
  const medLCX = lbX + 336 * s;
  const medLCY = pedLY - 64 * s + Math.sin(p2) * 4 * s;
  roundedRectPath(medLCX - 22 * s, pedLY - 16 * s, 44 * s, 16 * s, 5 * s);
  fillAndStroke(COL.goldDeep, COL.outline, thinStrokeW);
  drawGoldMedallion(medLCX, medLCY, 44 * s, 1.25 * s);

  // =========================================================================
  // 5. CENTER ZONE: LEDGER BOOKS, PLANTER POT, DIVIDEND TREE & WATERING CAN
  // Bounding Box: x in [cx - 210*s, cx + 250*s], y in [cy - 375*s, cy + 395*s]
  // Every element inside this central zone is strictly separated!
  // =========================================================================

  // 5A. Two Stacked Financial Ledger Books on baseLineY (y: cy + 315*s to cy + 395*s)
  const book1W = 340 * s;
  const book1H = 40 * s;
  const book1X = cx - book1W * 0.5;
  const book1Y = baseLineY - book1H;

  roundedRectPath(book1X, book1Y, book1W, book1H, 10 * s);
  fillAndStroke(COL.bookBlue, COL.outline, strokeW);

  // Book 1 page edge block on right
  roundedRectPath(book1X + book1W - 76 * s, book1Y + 7 * s, 66 * s, book1H - 14 * s, 6 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, thinStrokeW);

  // Book 1 spine label pill on left
  roundedRectPath(book1X + 22 * s, book1Y + 13 * s, 95 * s, 14 * s, 7 * s);
  fillAndStroke(COL.goldMid, COL.outline, 2.5 * s);

  // Upper Ledger Book 2 (y: cy + 275*s to cy + 315*s)
  const book2W = 284 * s;
  const book2H = 40 * s;
  const book2X = cx - book2W * 0.5;
  const book2Y = book1Y - book2H;

  roundedRectPath(book2X, book2Y, book2W, book2H, 10 * s);
  fillAndStroke(COL.bookPurple, COL.outline, strokeW);

  // Book 2 page edge block on left
  roundedRectPath(book2X + 10 * s, book2Y + 7 * s, 62 * s, book2H - 14 * s, 6 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, thinStrokeW);

  // Book 2 spine label pill on right
  roundedRectPath(book2X + book2W - 115 * s, book2Y + 13 * s, 90 * s, 14 * s, 7 * s);
  fillAndStroke(COL.leafLight, COL.outline, 2.5 * s);

  // 5B. Modern Ceramic Planter Pot sitting flush on Book 2 (y: cy + 145*s to cy + 275*s)
  const potBottomY = book2Y;
  const potRimTopY = cy + 145 * s;
  const potRimH = 26 * s;
  const potBodyTopY = potRimTopY + potRimH;
  const potTopHalfW = 104 * s;
  const potBotHalfW = 82 * s;

  // Pot Tapered Body
  ctx.beginPath();
  ctx.moveTo(cx - potTopHalfW, potBodyTopY);
  ctx.lineTo(cx + potTopHalfW, potBodyTopY);
  ctx.lineTo(cx + potBotHalfW, potBottomY);
  ctx.lineTo(cx - potBotHalfW, potBottomY);
  ctx.closePath();
  fillAndStroke(COL.potTerracotta, COL.outline, strokeW);

  // Right-side flat vector shade on Pot Body
  ctx.save();
  ctx.clip();
  ctx.fillStyle = COL.potTerracottaDark;
  ctx.fillRect(cx + 28 * s, potBodyTopY, potTopHalfW, potBottomY - potBodyTopY);
  ctx.restore();

  // Re-stroke Pot Body outline
  ctx.beginPath();
  ctx.moveTo(cx - potTopHalfW, potBodyTopY);
  ctx.lineTo(cx + potTopHalfW, potBodyTopY);
  ctx.lineTo(cx + potBotHalfW, potBottomY);
  ctx.lineTo(cx - potBotHalfW, potBottomY);
  ctx.closePath();
  fillAndStroke(null, COL.outline, strokeW);

  // Pot Rim Collar
  const rimW = 236 * s;
  roundedRectPath(cx - rimW * 0.5, potRimTopY, rimW, potRimH, 10 * s);
  fillAndStroke(COL.potTerracotta, COL.outline, strokeW);

  // Center Gold Dollar Badge on Front of Planter Pot
  const potBadgeY = (potBodyTopY + potBottomY) * 0.5;
  drawGoldMedallion(cx, potBadgeY, 32 * s, 0.95 * s);

  // 5C. Compounding Dividend Plant (Stem, 3 Tiers of Leaves, & Non-Overlapping Gold Fruits)
  // Rises from potRimTopY (cy + 145*s) up to Top Crown Medallion (cy - 105*s)
  const treeSway = Math.sin(p2) * 4.5 * s;
  const stemBaseY = potRimTopY;
  const stemTopY = cy - 82 * s;

  // Central Botanical Stem
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = 14 * s;
  ctx.beginPath();
  ctx.moveTo(cx, stemBaseY);
  ctx.quadraticCurveTo(cx + treeSway * 0.5, (stemBaseY + stemTopY) * 0.5, cx + treeSway, stemTopY);
  ctx.stroke();

  ctx.strokeStyle = COL.leafMid;
  ctx.lineWidth = 6 * s;
  ctx.beginPath();
  ctx.moveTo(cx, stemBaseY - 4 * s);
  ctx.quadraticCurveTo(cx + treeSway * 0.5, (stemBaseY + stemTopY) * 0.5, cx + treeSway, stemTopY + 4 * s);
  ctx.stroke();

  // 3 Symmetrical Branch Tiers (Leaves sit near stem; Gold Coins sit at outer branch tips with clear gaps)
  const tiers = [
